/* Wot Design Uni control overrides retain the existing Figma layout. */
.tuneng-app{--wot-color-theme:#1a7a4a;--wot-button-primary-bg-color:#1a7a4a;--wot-button-primary-color:#fff}.tuneng-app .wd-button{border:0}.shop-back,.shop-bag{display:flex!important;width:72rpx!important;height:72rpx!important;min-width:72rpx!important;box-sizing:border-box!important;align-items:center!important;justify-content:center!important;margin:0!important;padding:0!important;border:1rpx solid #dce9df!important;border-radius:50%!important;background:#fff!important;box-shadow:0 5rpx 14rpx rgba(22,65,39,.1)!important;color:#17472b!important;line-height:1!important}.shop-back .wd-icon{transform:translateX(1rpx)}.shop-bag .wd-icon{transform:none}.shop-main-action{border:0!important}.accessory-card .wd-button{display:flex!important;width:52rpx!important;height:52rpx!important;min-width:52rpx!important;padding:0!important;align-items:center!important;justify-content:center!important;border-radius:50%!important;background:#1a7a4a!important;color:#fff!important}.accessory-card .wd-button__content{display:flex!important;width:100%!important;height:100%!important;align-items:center!important;justify-content:center!important}.accessory-card .wd-icon{margin:0!important;color:#fff!important}.points-item .wd-button{min-width:0!important;border:0!important;background:#e6f5e9!important;color:#176b3c!important}.points-item .wd-button[disabled]{opacity:1}
.plan-buy-button{width:430rpx!important;margin:0 auto!important}.plan-buy-button .wd-button__content{display:flex!important;width:100%!important;align-items:center!important;justify-content:center!important;gap:8rpx;transform:translateY(-2rpx)}
.scan-button{width:560rpx!important;height:104rpx!important;min-width:560rpx!important;gap:0!important;border-radius:54rpx!important}.scan-button-content{display:flex!important;width:100%!important;height:100%!important;flex-direction:row!important;flex-wrap:nowrap!important;align-items:center!important;justify-content:center!important;gap:16rpx;white-space:nowrap;transform:translateY(-1rpx)}.scan-button-content svg{display:block;flex:0 0 32rpx}.scan-button-content text{display:block;flex:0 0 auto;margin:0!important;color:#fff;font-size:30rpx!important;font-weight:700;line-height:1!important;transform:translateY(-2rpx)}

/* Native-device sizing: keep the scroll region and navigation stable on every screen. */
.tuneng-app{width:100%;min-width:0;height:100vh;min-height:100vh;box-sizing:border-box}.content{width:100%;min-width:0;min-height:0;flex:1 1 0}.home-tab,.rental-tab,.carbon-tab,.community-tab,.profile-tab,.shop-tab{width:100%;min-width:0;box-sizing:border-box}.bottom-nav{width:100%;min-width:0;box-sizing:border-box;flex:none}.bottom-nav>view{min-width:0;flex:1}
